#!/usr/bin/env python3
"""A window for the CI run that drives a real screen. Fixed places, so a drag can name pixels: a status label and a button (10,40), an entry
(10,80), a slider (10,120), a long text in a scrolled window (10,160). Each thing that happens writes itself into a label the screen can be read for."""
import gi
gi.require_version("Gtk", "3.0")
from gi.repository import Gtk

win = Gtk.Window(title="navvied-target")
box = Gtk.Fixed()
status = Gtk.Label(label="idle")
button = Gtk.Button(label="Press")
button.connect("clicked", lambda _b: status.set_text("pressed"))
entry = Gtk.Entry()
entry.get_accessible().set_name("navvied-entry")
slider_label = Gtk.Label(label="slider 0")
slider = Gtk.Scale.new_with_range(Gtk.Orientation.HORIZONTAL, 0, 100, 1)
slider.set_draw_value(False)
slider.connect("value-changed", lambda s: slider_label.set_text("slider %d" % round(s.get_value())))
scroll_label = Gtk.Label(label="scrolled 0")
view = Gtk.TextView()
view.get_buffer().set_text("\n".join("line %d" % n for n in range(1, 301)))
scroller = Gtk.ScrolledWindow()
scroller.add(view)
scroller.set_size_request(300, 80)
scroller.get_vadjustment().connect("value-changed", lambda a: scroll_label.set_text("scrolled %d" % round(a.get_value())))
box.put(status, 10, 10)
box.put(button, 10, 40)
box.put(entry, 100, 40)
box.put(slider_label, 10, 80)
box.put(slider, 100, 80)
slider.set_size_request(200, 30)
box.put(scroll_label, 10, 120)
box.put(scroller, 10, 150)
win.add(box)
win.set_default_size(340, 250)
win.set_resizable(False)
win.connect("destroy", Gtk.main_quit)
win.show_all()
Gtk.main()
